<!doctype html><html lang="es"><head><meta charset="utf-8"><style>
@page{margin:0}body{margin:0;background:#f3f3f1;color:#242424;font-family:DejaVu Sans,Arial,sans-serif}.ticket{margin:18px auto;width:92%;background:#fff;border-radius:18px;overflow:hidden;border:1px solid #ddd}.head{height:105px;background:#252525;text-align:center;padding:12px 20px}.logo{height:80px;max-width:430px;object-fit:contain}.title{text-align:center;font-size:22px;font-weight:bold;margin:22px 0 12px}.status{display:inline-block;background:#dff4e3;color:#18743a;border-radius:18px;padding:8px 24px;font-weight:bold;font-size:14px}.code{margin:18px 20px;background:#f1f1ef;border-radius:10px;text-align:center;padding:12px}.code small{display:block;letter-spacing:2px;color:#777}.code strong{font-size:20px;letter-spacing:1px}.info{margin:0 22px}.row{border-bottom:1px solid #ddd;padding:9px 0}.label{color:#777;font-size:10px;text-transform:uppercase;letter-spacing:1px}.value{font-size:14px;font-weight:bold;margin-top:3px}.money{margin:18px 20px;background:#f4f4f2;border-radius:10px;padding:12px;display:table;width:calc(100% - 40px);table-layout:fixed}.money div{display:table-cell;text-align:center;border-right:1px solid #ccc}.money div:last-child{border:0}.money small{display:block;color:#777}.money strong{font-size:16px}.balance{color:#d45c12}.foot{border-top:2px dashed #aaa;margin-top:18px;padding:15px 22px;text-align:center;font-size:11px;letter-spacing:1px}.qr{font-size:10px;color:#777;margin-top:10px}
</style></head><body><div class="ticket"><div class="head"><img class="logo" src="{{ $logo }}"></div><div class="title">PASE DE RESERVA</div><div style="text-align:center"><span class="status">{{ $booking->booking_status === 'CONFIRMADA' ? 'CONFIRMADA' : $booking->booking_status }}</span></div><div class="code"><small>CÓDIGO DE RESERVA</small><strong>{{ $booking->code }}</strong></div><div class="info"><div class="row"><div class="label">Cliente</div><div class="value">{{ $booking->customer->name }}</div></div><div class="row"><div class="label">Habitación</div><div class="value">{{ $booking->room->name }} · {{ $booking->room->category->name }}</div></div><div class="row"><div class="label">Fecha y horario</div><div class="value">{{ $booking->starts_at->timezone('America/Santiago')->format('d/m/Y · H:i') }} — {{ $booking->ends_at->timezone('America/Santiago')->format('H:i') }}</div></div><div class="row"><div class="label">Duración</div><div class="value">{{ $booking->duration_minutes / 60 }} horas</div></div></div><div class="money"><div><small>TOTAL</small><strong>${{ number_format($booking->price_final + $booking->addonsTotal(),0,',','.') }}</strong></div><div><small>PAGADO</small><strong>${{ number_format($paid,0,',','.') }}</strong></div><div><small>SALDO</small><strong class="balance">${{ number_format($balance,0,',','.') }}</strong></div></div><div class="foot"><strong>PRESENTAR EN RECEPCIÓN</strong><div class="qr">Código de reserva: {{ $booking->code }}<br>Este pase es un comprobante operacional, no un documento tributario.</div></div></div></body></html>
